<?php declare(strict_types=1);

namespace App\PHPStan\Codeception;

use Codeception\Actor;
use PhpParser\Node\Expr\MethodCall;
use PHPStan\Analyser\Scope;
use PHPStan\Reflection\MethodReflection;
use PHPStan\Type\DynamicMethodReturnTypeExtension;
use PHPStan\Type\Type;

/**
 * `$I->grabService(Foo::class)` of the Codeception actors (generated by `codecept build` from
 * `Contributte\Codeception\Module\NetteDIModule::grabService()`) is declared `object`, but it returns
 * `Container::getByType($service)`, i.e. an instance of the given class: the call gets the type of that class.
 */
class GrabServiceReturnTypeExtension implements DynamicMethodReturnTypeExtension
{
    #[\Override]
    public function getClass() : string
    {
        return Actor::class;
    }

    #[\Override]
    public function isMethodSupported(MethodReflection $methodReflection) : bool
    {
        return $methodReflection->getName() === 'grabService';
    }

    #[\Override]
    public function getTypeFromMethodCall(MethodReflection $methodReflection, MethodCall $methodCall, Scope $scope) : ?Type
    {
        $argument = $methodCall->getArgs()[0] ?? null;

        if ($argument === null) {
            return null;
        }

        $classType = $scope->getType($argument->value)->getClassStringObjectType();

        if (!$classType->isObject()->yes()) {
            return null;
        }

        return $classType;
    }
}
